// Self-contained sample imagery for design-system previews.
// Optimized (≈420–560px JPEG) copies of OWNED brand photos, embedded as base64
// data URIs so preview cards render real imagery with no remote/CDN dependency
// (remote URLs are fragile in the render sandbox, and break in CSS url() — see
// the encodeURIComponent/quote bug). Source photos live in apps/*/public.
// Regenerate via scripts if the source art changes. Not shipped to the live apps.

export const SAMPLE_HERO_FARM = "data:image/jpeg;base64,";
export const SAMPLE_HERO_NURSERY = "data:image/jpeg;base64,";
export const SAMPLE_PRODUCT_APPLE = "data:image/jpeg;base64,";
export const SAMPLE_PRODUCT_GRAPE = "data:image/jpeg;base64,";
